use crate::color::D3Color;

/// HSL color representation
#[derive(Debug, Clone, Copy)]
pub struct Hsl {
    pub h: f64, // Hue in degrees [0, 360)
    pub s: f64, // Saturation [0, 1]
    pub l: f64, // Lightness [0, 1]
    pub a: f64, // Alpha [0, 1]
}

impl Hsl {
    /// Create a new HSL color.
    pub fn new(h: f64, s: f64, l: f64) -> Self {
        Self { h, s, l, a: 1.0 }
    }

    /// Create from a D3Color (RGB).
    pub fn from_rgb(color: &D3Color) -> Self {
        let r = color.r as f64;
        let g = color.g as f64;
        let b = color.b as f64;

        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max + min) / 2.0;

        if (max - min).abs() < f64::EPSILON {
            return Self {
                h: 0.0,
                s: 0.0,
                l,
                a: color.a as f64,
            };
        }

        let d = max - min;
        let s = if l > 0.5 {
            d / (2.0 - max - min)
        } else {
            d / (max + min)
        };

        let h = if (max - r).abs() < f64::EPSILON {
            (g - b) / d + if g < b { 6.0 } else { 0.0 }
        } else if (max - g).abs() < f64::EPSILON {
            (b - r) / d + 2.0
        } else {
            (r - g) / d + 4.0
        };

        Self {
            h: h * 60.0,
            s,
            l,
            a: color.a as f64,
        }
    }

    /// Convert to D3Color (RGB).
    pub fn to_rgb(&self) -> D3Color {
        let h = self.h / 360.0;
        let s = self.s;
        let l = self.l;

        if s.abs() < f64::EPSILON {
            let v = l as f32;
            return D3Color {
                r: v,
                g: v,
                b: v,
                a: self.a as f32,
            };
        }

        let q = if l < 0.5 {
            l * (1.0 + s)
        } else {
            l + s - l * s
        };
        let p = 2.0 * l - q;

        fn hue_to_rgb(p: f64, q: f64, mut t: f64) -> f64 {
            if t < 0.0 {
                t += 1.0;
            }
            if t > 1.0 {
                t -= 1.0;
            }
            if t < 1.0 / 6.0 {
                return p + (q - p) * 6.0 * t;
            }
            if t < 1.0 / 2.0 {
                return q;
            }
            if t < 2.0 / 3.0 {
                return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
            }
            p
        }

        D3Color {
            r: hue_to_rgb(p, q, h + 1.0 / 3.0) as f32,
            g: hue_to_rgb(p, q, h) as f32,
            b: hue_to_rgb(p, q, h - 1.0 / 3.0) as f32,
            a: self.a as f32,
        }
    }
}
